#!/usr/bin/env bash
# Generated by the Neutrino Translator. Proves the PostgreSQL capability-spec against a
# real PostgreSQL container via docker + psql (no Python). All dynamic SQL is
# fed through quoted heredocs, so the shell never interpolates scenario values;
# SQL string literals are '-escaped.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
CID=$(docker run -d -e POSTGRES_PASSWORD=test -e POSTGRES_USER=test -e POSTGRES_DB=neutrino postgres:16-alpine)
cleanup(){ docker rm -f "$CID" >/dev/null 2>&1 || true; }
trap cleanup EXIT
psql(){ docker exec -i "$CID" psql -v ON_ERROR_STOP=1 -U test -d neutrino "$@"; }
echo 'waiting for postgres...'
ready=0
for _ in $(seq 1 60); do
  if psql -tAq -c 'SELECT 1' >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
[ "$ready" = 1 ] || { echo 'FAIL: postgres did not become ready'; exit 1; }

echo NEUTRINO_STAGE=compile
psql -q < "$HERE/schema.sql" >/dev/null
psql -q < "$HERE/procedure.sql" >/dev/null
echo NEUTRINO_STAGE=runtime

run(){ psql -tAq >/dev/null <<'SQL'
SELECT attest_token_mint('mint-001');
SELECT execute_token_mint('mint-001', 'token-reserve', 'holder-001', 2500, 'EUR', 1);
SQL
}
expect_fail(){ if psql -tAq >/dev/null 2>&1; then echo "FAIL: $1 not refused"; exit 1; fi; }

# 1. attestation gate: execute without a prior attest is refused
expect_fail 'unattested execute' <<'SQL'
SELECT execute_token_mint('mint-001', 'token-reserve', 'holder-001', 2500, 'EUR', 1);
SQL
echo '  [1] attestation gate: PASS'

# 2. happy path (attest+execute): balances move; a missing ledger row is upserted
run
V=$(psql -tAq <<'SQL'
SELECT COALESCE(SUM(balance),0) FROM ledger_balance WHERE ledger='token.balance';
SQL
)
[ "$V" = "2500" ] || { echo "FAIL: net mismatch"; exit 1; }
V=$(psql -tAq <<'SQL'
SELECT COALESCE(SUM(balance),0) FROM ledger_balance WHERE ledger='token.supply';
SQL
)
[ "$V" = "-2500" ] || { echo "FAIL: net mismatch"; exit 1; }
N=$(psql -tAq <<'SQL'
SELECT count(*) FROM postings WHERE idempotency_key='mint-001';
SQL
)
[ "$N" = "2" ] || { echo "FAIL: postings=$N"; exit 1; }
echo '  [2] happy path balances + upsert: PASS'

# 3. replay: re-executing a reconciled key is refused
expect_fail 'replay' <<'SQL'
SELECT execute_token_mint('mint-001', 'token-reserve', 'holder-001', 2500, 'EUR', 1);
SQL
echo '  [3] replay refused: PASS'

# 4. bad transition: attesting a reconciled key is refused
expect_fail 'bad transition' <<'SQL'
SELECT attest_token_mint('mint-001');
SQL
echo '  [4] bad transition refused: PASS'

# 5. reconciliation: no drift on the happy path
D=$(psql -tAq <<'SQL'
SELECT count(*) FROM (SELECT idempotency_key FROM postings GROUP BY idempotency_key HAVING SUM(signed_amount)<>0) x;
SQL
)
[ "$D" = "0" ] || { echo "FAIL: unexpected drift rows=$D"; exit 1; }
echo '  [5] reconciliation no drift: PASS'

# 6. reconciliation detects an injected drift
psql -q >/dev/null <<'SQL'
INSERT INTO postings(procedure,entry,ledger,party,amount,currency,signed_amount,idempotency_key)
VALUES ('token_mint','injected','injected','injected',1,'X',1,'mint-001');
SQL
D2=$(psql -tAq <<'SQL'
SELECT count(*) FROM (SELECT idempotency_key FROM postings GROUP BY idempotency_key HAVING SUM(signed_amount)<>0) x;
SQL
)
[ "$D2" -ge "1" ] || { echo "FAIL: drift not detected"; exit 1; }
echo '  [6] reconciliation detects injected drift: PASS'

# 7. atomic rollback: a rolled-back attest+execute leaves no rows
psql -q >/dev/null <<'SQL'
BEGIN;
SELECT attest_token_mint('txn-rollback');
SELECT execute_token_mint('txn-rollback', 'token-reserve', 'holder-001', 2500, 'EUR', 1);
ROLLBACK;
SQL
NR=$(psql -tAq <<'SQL'
SELECT count(*) FROM postings WHERE idempotency_key='txn-rollback';
SQL
)
[ "$NR" = "0" ] || { echo "FAIL: rollback left rows=$NR"; exit 1; }
echo '  [7] atomic rollback: PASS'

echo 'ALL POSTGRES CHECKS PASSED'
